def has_close_elements(numbers: list[float], threshold: float) -> bool:
    """Return True if any two numbers in the list are closer to each other
    than the given threshold."""
    if threshold <= 0:
        # Distances are non‑negative; no pair can be closer than 0 or a negative value
        return False
    n = len(numbers)
    if n < 2:
        return False
    sorted_numbers = sorted(numbers)
    for i in range(1, n):
        if sorted_numbers[i] - sorted_numbers[i - 1] < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    """Return a list of top-level balanced parentheses groups from the input string."""
    groups = []
    depth = 0
    buffer = []
    for ch in paren_string:
        if ch == ' ':
            continue
        if ch == '(':
            if depth == 0:
                buffer = []  # start a new group
            depth += 1
        elif ch == ')':
            depth -= 1
        buffer.append(ch)
        if depth == 0 and buffer:
            groups.append(''.join(buffer))
    return groups

