def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    neg_inf = -10 ** 15
    # dp[x1][x2] holds best sum when both walkers have taken (x1-1)+(y1-1) steps
    prev = [[neg_inf] * (N + 1) for _ in range(N + 1)]
    # Starting position (1,1) for both
    prev[1][1] = grid[1][1]
    # Iterate over steps s = x + y, starting from s=3 to 2*N
    for s in range(3, 2 * N + 1):
        cur = [[neg_inf] * (N + 1) for _ in range(N + 1)]
        # x ranges within [1, N] and y = s - x must be within [1, N]
        min_x = max(1, s - N)
        max_x = min(N, s - 1)
        for x1 in range(min_x, max_x + 1):
            y1 = s - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(min_x, max_x + 1):
                y2 = s - x2
                if y2 < 1 or y2 > N:
                    continue
                best = prev[x1][x2]         # both came from left (1,1)
                if x1 > 1:
                    best = max(best, prev[x1 - 1][x2])     # first down, second left
                    if x2 > 1:
                        best = max(best, prev[x1 - 1][x2 - 1])  # both down
                if x2 > 1:
                    best = max(best, prev[x1][x2 - 1])  # first left, second down
                if best == neg_inf:
                    continue
                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                cur[x1][x2] = best + add
        prev = cur
    return prev[N][N] if prev[N][N] != neg_inf else 0

def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid with 1-indexing
    a = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        a[x][y] = v

    # DP dimensions: dp[i1][i2] after t steps
    # Initialize with very small values
    NEG = -10**15
    dp = [[NEG] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = a[1][1]

    # t is number of steps taken (moves) so far
    # After t steps, coordinates satisfy i+j = t+2 (1-indexed)
    for t in range(1, 2 * N - 1):
        newdp = [[NEG] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = t + 2 - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = t + 2 - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG
                # previous positions (down/right moves)
                for pi1 in (i1, i1 - 1):
                    for pi2 in (i2, i2 - 1):
                        if pi1 < 1 or pi2 < 1:
                            continue
                        if dp[pi1][pi2] == NEG:
                            continue
                        val = dp[pi1][pi2]
                        # add current cell values
                        if i1 == i2 and j1 == j2:
                            val += a[i1][j1]
                        else:
                            val += a[i1][j1] + a[i2][j2]
                        if val > best:
                            best = val
                newdp[i1][i2] = best
        dp = newdp

    return dp[N][N] if dp[N][N] != NEG else 0

def max_value_on_paths(N, grid_values):
    # Build grid with zero-based indices
    grid = [[0] * N for _ in range(N)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        # Convert to 0-indexed
        grid[x - 1][y - 1] = v

    # Edge case: N == 1
    if N == 1:
        return grid[0][0]

    # Initialize dp arrays
    NEG = -10**15
    dp_prev = [[NEG] * N for _ in range(N)]
    dp_prev[0][0] = grid[0][0]

    max_step = 2 * N - 2  # steps from 0 to max_step inclusive
    for step in range(1, max_step + 1):
        dp_curr = [[NEG] * N for _ in range(N)]
        # i1 and i2 are row indices (0-indexed)
        for i1 in range(max(0, step - (N - 1)), min(N, step + 1)):
            j1 = step - i1
            if j1 < 0 or j1 >= N:
                continue
            val1 = grid[i1][j1]
            for i2 in range(max(0, step - (N - 1)), min(N, step + 1)):
                j2 = step - i2
                if j2 < 0 or j2 >= N:
                    continue
                val2 = grid[i2][j2]
                # Add value from both positions, avoid double counting
                add_val = val1
                if i2 != i1 or j2 != j1:
                    add_val += val2

                best_prev = NEG
                # Try all 4 predecessor combinations
                for pi1 in (i1 - 1, i1):
                    if pi1 < 0 or pi1 >= N:
                        continue
                    pj1 = step - 1 - pi1
                    if pj1 < 0 or pj1 >= N:
                        continue
                    for pi2 in (i2 - 1, i2):
                        if pi2 < 0 or pi2 >= N:
                            continue
                        pj2 = step - 1 - pi2
                        if pj2 < 0 or pj2 >= N:
                            continue
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val > best_prev:
                            best_prev = prev_val
                if best_prev != NEG:
                    dp_curr[i1][i2] = best_prev + add_val
        dp_prev = dp_curr

    return dp_prev[N - 1][N - 1] if dp_prev[N - 1][N - 1] != -10**15 else 0

def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid with 1‑based indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = v

    NEG_INF = -10**15
    # dp_prev[i1][i2] – maximum value when the first path is at (i1, j1)
    # and the second path is at (i2, j2) where j1 + i1 = j2 + i2 = step
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    for step in range(2, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, step - N)
        i_max = min(N, step - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = step - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = step - i2
                if j2 < 1 or j2 > N:
                    continue

                best = NEG_INF
                # Possible previous positions: up or left for each walker
                for di1 in (-1, 0):
                    pi1 = i1 + di1
                    if pi1 < 1 or pi1 > N:
                        continue
                    for di2 in (-1, 0):
                        pi2 = i2 + di2
                        if pi2 < 1 or pi2 > N:
                            continue
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val > best:
                            best = prev_val
                if best == NEG_INF:
                    continue

                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_cur[i1][i2] = best + add

        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG_INF else 0

def find_number_combinations():
    def is_valid(n):
        if n < 100 or n > 999:
            return False
        d = []
        for _ in range(3):
            d.append(n % 10)
            n //= 10
        if 0 in d:
            return False
        return len(set(d)) == 3

    result = []
    for a in range(123, 988):
        if not is_valid(a):
            continue
        b = 2 * a
        c = 3 * a
        if not (is_valid(b) and is_valid(c)):
            continue
        result.append((a, b, c))
    return result

def find_number_combinations():
    def is_valid(num):
        if num < 100 or num > 999:
            return False
        s = str(num)
        if '0' in s:
            return False
        return len(set(s)) == 3

    combinations = []
    for first in range(123, 334):  # 333 is the maximum possible first number (3 * 333 = 999)
        if not is_valid(first):
            continue
        second = first * 2
        third = first * 3
        if is_valid(second) and is_valid(third):
