def cantor_numbering(N: int) -> str:
    # Find diagonal d such that d(d+1)/2 >= N
    lo, hi = 1, 1
    while hi * (hi + 1) // 2 < N:
        hi <<= 1  # double hi
    while lo < hi:
        mid = (lo + hi) // 2
        if mid * (mid + 1) // 2 >= N:
            hi = mid
        else:
            lo = mid + 1
    d = lo
    prev_total = (d - 1) * d // 2
    idx = N - prev_total  # 1-based index inside the diagonal
    if d % 2 == 0:
        numer = idx
        denom = d - idx + 1
    else:
        numer = d - idx + 1
        denom = idx
    return f"{numer}/{denom}"

def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")
    total = 0
    d = 1
    while total + d < N:
        total += d
        d += 1
    k = N - total
    if d % 2 == 1:
        numerator = d - k + 1
        denominator = k
    else:
        numerator = k
        denominator = d - k + 1
    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    # If impossible to insert K multiplication signs
    if K >= N:
        return 0
    # dp[i][k] = max product for first i digits with k multiplication signs
    dp = [[None] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1  # empty product
    # Precompute integer values of all substrings to avoid repeated int conversion
    substr_val = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + (ord(num_str[j - 1]) - 48)
            substr_val[i][j] = val
    for i in range(1, N + 1):
        # No multiplication sign
        dp[i][0] = substr_val[0][i]
    for k in range(1, K + 1):
        for i in range(k + 1, N + 1):  # need at least k+1 digits to place k signs
            max_prod = None
            for j in range(k, i):
                prev = dp[j][k - 1]
                if prev is None:
                    continue
                prod = prev * substr_val[j][i]
                if (max_prod is None) or (prod > max_prod):
                    max_prod = prod
            dp[i][k] = max_prod
    return dp[N][K] if dp[N][K] is not None else 0

def max_product(num_str: str, N: int, K: int) -> int:
    # Precompute all substring values
    N = len(num_str)  # Ensure consistency with provided N
    val = [[0] * N for _ in range(N)]
    for i in range(N):
        cur = 0
        for j in range(i, N):
            cur = cur * 10 + int(num_str[j])
            val[i][j] = cur

    # DP table: dp[i][k] = max product for substring 0..i (inclusive) using k multiplications
    dp = [[0] * (K + 1) for _ in range(N)]
    # Base case: no multiplications, entire substring value
    for i in range(N):
        dp[i][0] = val[0][i]

    # Fill DP
    for k in range(1, K + 1):
        for i in range(k, N):
            best = 0
            # split between positions j and i (j < i)
            for j in range(k - 1, i):
                prod = dp[j][k - 1] * val[j + 1][i]
                if prod > best:
                    best = prod
            dp[i][k] = best

    return dp[N - 1][K] if K <= N - 1 else 0

def max_product(num_str: str, N: int, K: int) -> int:
    # Ensure N matches the string length; use provided N only for consistency
    if N != len(num_str):
        N = len(num_str)
    # If no cuts, return the number itself
    if K == 0:
        return int(num_str) if num_str else 0
    # If K is greater than maximum possible cuts (N-1), return 0
    if K > N - 1:
        return 0
    # DP table: dp[i][k] = maximum product for prefix of length i with k cuts
    dp = [[-1] * (K + 1) for _ in range(N + 1)]
    # Base: no cuts => product is the integer value of the prefix
    for i in range(1, N + 1):
        dp[i][0] = int(num_str[0:i])
    # Fill DP for cuts from 1 to K
    for k in range(1, K + 1):
        # Need at least k+1 digits to place k cuts
        for i in range(k + 1, N + 1):
            best = -1
            # j is the start index of the last segment
            for j in range(k, i):
                val = int(num_str[j:i])
                prev = dp[j][k - 1]
                if prev == -1:
                    continue
                prod = prev * val
                if prod > best:
                    best = prod
            dp[i][k] = best
    return dp[N][K] if dp[N][K] != -1 else 0

