def verify_isbn(isbn: str) -> str:
    # Split into groups, expect 4 parts
    parts = isbn.split('-')
    if len(parts) != 4:
        raise ValueError("ISBN must contain three dashes separating four groups")
    # Concatenate all characters: should be 10 characters
    raw = ''.join(parts)
    if len(raw) != 10:
        raise ValueError("ISBN must contain exactly ten characters (digits or X) ignoring dashes")
    # Convert to numeric values
    digits = []
    for ch in raw:
        if ch.isdigit():
            digits.append(int(ch))
        elif ch in ('X', 'x'):
            digits.append(10)
        else:
            raise ValueError(f"Invalid character '{ch}' in ISBN")
    # Compute checksum: sum_{i=1}^{10} i * digit_i
    checksum = sum((i + 1) * d for i, d in enumerate(digits))
    if checksum % 11 == 0:
        return "Right"
    # Need to correct the last digit
    sum_without_last = sum((i + 1) * d for i, d in enumerate(digits[:-1]))
    # Desired last digit such that (sum_without_last + 10*last_digit) % 11 == 0
    # So last_digit ≡ (-sum_without_last) * inv10 mod 11, where inv10 = 10 (since 10*10 ≡ 1 mod 11)
    desired_last = (-sum_without_last * 10) % 11
    if desired_last == 10:
        corrected_digit = 'X'
    else:
        corrected_digit = str(desired_last)
    # Build corrected ISBN string preserving original dash positions
    corrected_parts = [parts[0], parts[1], parts[2], corrected_digit]
    return '-'.join(corrected_parts)

def verify_isbn(isbn: str) -> str:
    # Split the ISBN into parts
    parts = isbn.split('-')
    if len(parts) != 4:
        return isbn  # format mismatch, return as is

    digits = parts[0] + parts[1] + parts[2] + parts[3]
    if len(digits) != 10:
        return isbn  # not 10 characters, return as is

    # Convert to numeric values
    values = []
    for i, ch in enumerate(digits):
        if i == 9:  # checksum character
            if ch.upper() == 'X':
                values.append(10)
            elif ch.isdigit():
                values.append(int(ch))
            else:
                return isbn  # invalid character
        else:
            if not ch.isdigit():
                return isbn
            values.append(int(ch))

    # Compute weighted sum
    weighted = sum((idx + 1) * val for idx, val in enumerate(values))
    if weighted % 11 == 0:
        return "Right"

    # Correct the checksum digit
    first_nine_sum = sum((i + 1) * values[i] for i in range(9))
    correct_val = first_nine_sum % 11
    corrected_digit = 'X' if correct_val == 10 else str(correct_val)

    # Build corrected ISBN with same hyphen positions
    corrected_parts = parts[:3] + [corrected_digit]
    return '-'.join(corrected_parts)

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Possible aisle positions (between rows/columns)
    horiz_positions = list(range(1, M))   # 1..M-1
    vert_positions = list(range(1, N))    # 1..N-1

    from itertools import combinations

    best_separated = -1
    best_horiz = []
    best_vert = []

    # Preprocess pairs for speed
    pairs = chatting_pairs

    def is_separated(p, horiz_set, vert_set):
        (x, y, p, q) = p
        if x != p:
            lo, hi = (x, p) if x < p else (p, x)
            for h in horiz_set:
                if lo < h < hi:
                    return True
        if y != q:
            lo, hi = (y, q) if y < q else (q, y)
            for v in vert_set:
                if lo < v < hi:
                    return True
        return False

    # Enumerate all combinations
    for horiz_combo in combinations(horiz_positions, K) if K > 0 else [()]:
        horiz_set = set(horiz_combo)
        for vert_combo in combinations(vert_positions, L) if L > 0 else [()]:
            vert_set = set(vert_combo)
            separated_count = 0
            for p in pairs:
                if is_separated(p, horiz_set, vert_set):
                    separated_count += 1
            if separated_count > best_separated:
                best_separated = separated_count
                best_horiz = list(horiz_combo)
                best_vert = list(vert_combo)

    # Build output strings
    horiz_str = ' '.join(map(str, sorted(best_horiz))) if K > 0 else ''
