def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    from itertools import combinations

    row_indices = list(range(1, M))      # possible horizontal aisles between row i and i+1
    col_indices = list(range(1, N))      # possible vertical aisles between col i and i+1

    best_count = -1
    best_rows = ()
    best_cols = ()

    for rows in combinations(row_indices, K):
        for cols in combinations(col_indices, L):
            separated_pairs = 0
            for r1, c1, r2, c2 in chatting_pairs:
                separated = False
                # Check horizontal aisle separation
                if r1 != r2:
                    for aisle in rows:
                        if (r1 <= aisle < r2) or (r2 <= aisle < r1):
                            separated = True
                            break
                # Check vertical aisle separation if not already separated
                if not separated and c1 != c2:
                    for aisle in cols:
                        if (c1 <= aisle < c2) or (c2 <= aisle < c1):
                            separated = True
                            break
                if separated:
                    separated_pairs += 1
            if separated_pairs > best_count:
                best_count = separated_pairs
                best_rows = rows
                best_cols = cols
            elif separated_pairs == best_count:
                # tie‑breaking by lexicographic order of indices
                if sorted(rows) < sorted(best_rows):
                    best_rows = rows
                    best_cols = cols
                elif sorted(rows) == sorted(best_rows) and sorted(cols) < sorted(best_cols):
                    best_cols = cols

    row_str = ' '.join(map(str, sorted(best_rows))) if best_rows else ''
    col_str = ' '.join(map(str, sorted(best_cols))) if best_cols else ''
    return (row_str, col_str)

def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    if n == 1:
        return 1 << m  # 2**m
    dp = [0] * n
    dp[0] = 1
    for _ in range(m):
        next_dp = [0] * n
        for pos, val in enumerate(dp):
            if val:
                next_dp[(pos + 1) % n] += val
                next_dp[(pos - 1) % n] += val
        dp = next_dp
    return dp[0]

def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    if n == 1:
        return 1 << m  # 2**m
    dp = [0] * n
    dp[0] = 1
    for _ in range(m):
        new = [0] * n
        for i, val in enumerate(dp):
            if val:
                left = (i - 1) % n
                right = (i + 1) % n
                new[left] += val
                new[right] += val
        dp = new
    return dp[0]

