def max_happiness(n: int, m: int, items: list) -> int:
    dp = [0] * (n + 1)
    for price, value in items:
        if price > n:
            continue
        for cap in range(n, price - 1, -1):
            cand = dp[cap - price] + value
            if cand > dp[cap]:
                dp[cap] = cand
    return dp[n]

def max_happiness(n: int, m: int, items: list[tuple[int, int]]) -> int:
    """
    Returns the maximum total importance value that can be obtained with the given budget.
    Each item's value is defined as `price * importance`.
    """
    dp = [0] * (n + 1)
    for price, importance in items:
        value = price * importance
        if price > n:
            continue
        for cap in range(n, price - 1, -1):
            new_val = dp[cap - price] + value
            if new_val > dp[cap]:
                dp[cap] = new_val
    return dp[n]

