    sorted_app = sorted(applicants, key=lambda x: (-x[1], x[0]))
    cutoff_rank = int(1.5 * m) - 1
    if cutoff_rank < 0:
        cutoff_rank = 0
    if cutoff_rank >= len(sorted_app):
