def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping:
            if mapping[enc] != orig:
                return "Failed"
        else:
            mapping[enc] = orig
    if len(mapping) < 26:
        return "Failed"
    decoded = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded.append(mapping[ch])
    return "".join(decoded)

def decode(encoded: str, original: str, message: str) -> str:
