    for e, o in zip(encoded, original):
        # Check forward mapping consistency
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            # Ensure bijection: no two encoded letters map to same original letter
            if o in reverse and reverse[o] != e:
