def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer `n` into `k` parts,
    where each part is at least `x` and the order of parts does not matter.
    """
    if k == 0:
        return 1 if n == 0 else 0
    m = n - k * x
    if m < 0:
        return 0
    dp = [[0] * (k + 1) for _ in range(m + 1)]
    for j in range(k + 1):
        dp[0][j] = 1
    for i in range(1, m + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]
    return dp[m][k]

def count_partitions(n: int, k: int, x: int) -> int:
    if k <= 0:
        return 1 if n == 0 else 0
    T = n - k * x
    if T < 0:
        return 0
    dp = [0] * (T + 1)
    dp[0] = 1
    for part in range(1, k + 1):
        for s in range(part, T + 1):
            dp[s] += dp[s - part]
    return dp[T]

def count_partitions(n: int, k: int, x: int) -> int:
    S = n - k * x
    if S < 0:
        return 0
    k = min(k, S)  # largest part cannot exceed S
    dp = [[0] * (k + 1) for _ in range(S + 1)]
    for j in range(k + 1):
        dp[0][j] = 1  # one way to partition 0
    for i in range(1, S + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]
    return dp[S][k]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    # At least the current sequence ending here
    total = 1
    # Iterate over all possible next numbers: positive integers <= last // 2
    for next_val in range(1, last // 2 + 1):
        total += count_sequences(n, next_val, memo)
    memo[last] = total
    return total

def count_coprime_pairs(x0: int, y0: int) -> int:
    if y0 % x0 != 0:
        return 0

    n = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            if _gcd(i, j) == 1:
                if i == j:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

