def count_coprime_pairs(x0: int, y0: int) -> int:
    """Return the number of ordered pairs (P, Q) of positive integers such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    The function works by letting P = x0 * a and Q = x0 * b. Then
    a * b = y0 / x0 and gcd(a, b) must be 1.  Each co‑prime factor pair
    (a, b) contributes 2 ordered pairs (x0 * a, x0 * b) and (x0 * b, x0 * a)
    unless a == b, in which case it contributes only one pair.
    """
    if y0 % x0 != 0:
        return 0

    quotient = y0 // x0
    count = 0
    import math
    limit = int(math.isqrt(quotient))
    for a in range(1, limit + 1):
        if quotient % a == 0:
            b = quotient // a
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start >= in_end or post_start >= post_end:
            return ''
        root = postorder[post_end - 1]
        # find root index in inorder
        in_root_idx = inorder_map[root]
        left_len = in_root_idx - in_start
        left_pre = helper(in_start, in_root_idx, post_start, post_start + left_len)
        right_pre = helper(in_root_idx + 1, in_end, post_start + left_len, post_end - 1)
        return root + left_pre + right_pre

    inorder_map = {char: idx for idx, char in enumerate(inorder)}
    return helper(0, len(inorder), 0, len(postorder))

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ''
    if len(inorder) == 1:
        return inorder
    root = postorder[-1]
    idx = inorder.index(root)
    left_in = inorder[:idx]
    right_in = inorder[idx + 1 :]
    left_post = postorder[: len(left_in)]
    right_post = postorder[len(left_in) : -1]
    return (
        root
        + preorder_traversal(left_in, left_post)
        + preorder_traversal(right_in, right_post)
    )

