def find_min_n_greater_than_k(k: int) -> int:
    import math
    gamma = 0.57721566490153286060651209  # Euler-Mascheroni constant

    def lower_bound(n: int) -> float:
        return math.log(n) + gamma + 1 / (2 * n + 1)

    def upper_bound(n: int) -> float:
        return math.log(n) + gamma + 1 / (2 * n)

    # Exponential search to find an upper bound for n
    high = 1
    while upper_bound(high) <= k:
        high *= 2

    low = 1
    # Binary search for the minimal n such that H_n > k
    while low < high:
        mid = (low + high) // 2
        if lower_bound(mid) > k:
            high = mid
        else:
            low = mid + 1
    return low

