    return len(visited)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Each rule allows a single digit to be transformed into another. 
    BFS explores all possible transformations. Returns count of unique numbers.
    """
    # Build mapping from digit to list of transformation targets
    trans_map = {}
    for src, dst in rules:
        trans_map.setdefault(str(src), []).append(str(dst))
    # BFS initialization
    start_str = str(n)
    visited_ints = {int(start_str)}
    queue = [start_str]
    while queue:
        cur = queue.pop(0)
        for i, ch in enumerate(cur):
            if ch in trans_map:
                for tgt in trans_map[ch]:
                    if tgt == ch:
                        continue  # skip no-op transformation
                    new_str = cur[:i] + tgt + cur[i+1:]
                    new_int = int(new_str)
                    if new_int not in visited_ints:
                        visited_ints.add(new_int)
                        queue.append(new_str)
    return len(visited_ints)

def generate_numbers(n, rules):
    from collections import deque
    start = str(n)
    visited = {start}
    q = deque([start])
    rule_dict = {}
    for x, y in rules:
        rule_dict.setdefault(x, []).append(y)
    while q:
        s = q.popleft()
        for i, ch in enumerate(s):
            d = int(ch)
            if d in rule_dict:
                for y in rule_dict[d]:
                    new_s = s[:i] + str(y) + s[i+1:]
                    if new_s not in visited:
                        visited.add(new_s)
                        q.append(new_s)
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluate if the given scenario is consistent with the statements and liar assignments.
    """
    # Convert names to uppercase for uniform comparison
    scenario = scenario.upper()
    liar_count = {name.upper() for name in liar_count}
    # Convert days_of_week to lowercase for easy detection
    days_lower = {day.lower() for day in days_of_week}

    for speaker, says in statements.items():
        speaker = speaker.upper()
        for raw_statement in says:
            # Skip empty statements
            if not raw_statement:
                continue
            # Determine if the statement contains a day of the week
            stmt_lower = raw_statement.lower()
            if any(day in stmt_lower for day in days_lower):
                continue  # ignore day-of-week statements

            # Remove trailing period if present and strip whitespace
            stmt = raw_statement.rstrip('.').strip()
            stmt_lower = stmt.lower()
            # Determine truth value of the statement
            if stmt_lower.startswith('i am guilty'):
                statement_truth = (speaker == scenario)
            elif stmt_lower.startswith('i am not guilty'):
                statement_truth = (speaker != scenario)
            elif ' is guilty' in stmt_lower:
                # Split on ' is guilty' to extract the subject name
                parts = stmt_lower.split(' is guilty')
                subject = parts[0].strip().upper()
                statement_truth = (subject == scenario)
            elif ' is not guilty' in stmt_lower:
                parts = stmt_lower.split(' is not guilty')
                subject = parts[0].strip().upper()
                statement_truth = (subject != scenario)
            else:
                # Unrecognized statement format; treat as inconsistent
                continue  # or: return False

            # Check consistency with liar status
            if speaker in liar_count:
                if statement_truth:
                    return False  # liar gave a true statement
            else:
                if not statement_truth:
                    return False  # truth-teller gave a false statement

    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal
    based on the given statements, disregarding any statements that mention
    a day of the week.
    """
    def statement_truth(speaker: str, stmt: str) -> bool:
        stmt_clean = stmt.strip().rstrip('.')
        # Speaker refers to themselves
        if stmt_clean.startswith("I am guilty"):
            return scenario == speaker
        if stmt_clean.startswith("I am not guilty"):
            return scenario != speaker
        # Other people
        if " is " in stmt_clean:
            person, rest = stmt_clean.split(" is ", 1)
            if rest == "guilty":
                return scenario == person
            if rest == "not guilty":
                return scenario != person
        # Unknown/unsupported statements are treated as False (inconsistent)
        return False

    for speaker, stmts in statements.items():
        is_liar = speaker in liar_count
        for stmt in stmts:
            # skip statements containing any day of the week
            if any(day in stmt for day in days_of_week):
                continue
            truth = statement_truth(speaker, stmt)
            # liars must state false, truth-tellers must state true
            if is_liar and truth:
                return False
            if not is_liar and not truth:
                return False
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    # Normalize names to upper case for comparison
    scenario = scenario.upper()
    liar_names = {name.upper() for name in liar_count}
    days = {day.upper() for day in days_of_week}

    def contains_day(text: str) -> bool:
        upper_text = text.upper()
        return any(day in upper_text for day in days)

    for speaker, stmt_list in statements.items():
        speaker_name = speaker.upper()
        is_liar = speaker_name in liar_names
        for stmt in stmt_list:
            if contains_day(stmt):
                continue  # skip statements about the day of the week

            stmt_lower = stmt.strip().lower()
            truth_val = None

            if stmt_lower.startswith("i "):
                if "am guilty" in stmt_lower:
                    guilty_status = True
                elif "am not guilty" in stmt_lower:
                    guilty_status = False
                else:
                    continue  # cannot parse, ignore
                truth_val = (scenario == speaker_name) == guilty_status

            else:
                # Expected format: "<NAME> is guilty." or "<NAME> is not guilty."
                if " is guilty" in stmt_lower:
                    subject_raw, _ = stmt_lower.split(" is guilty", 1)
                    guilty_status = True
                elif " is not guilty" in stmt_lower:
                    subject_raw, _ = stmt_lower.split(" is not guilty", 1)
                    guilty_status = False
                else:
                    continue  # cannot parse, ignore

                subject_raw = subject_raw.strip()
                subject_name = subject_raw.upper()
                truth_val = (subject_name == scenario) == guilty_status

            if truth_val is None:
                continue  # skip unparsable statements

            if is_liar:
                if truth_val:
                    return False  # liar told a true statement
            else:
                if not truth_val:
                    return False  # truthful person made a false statement

    return True

