def min_remaining_space(V: int, n: int, volumes: list[int]) -> int:
    # Boolean DP array where dp[s] indicates whether sum s is achievable
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        if vol > V:
            continue
        # Update dp array from higher sums to lower to avoid reuse of the same item
        for s in range(V, vol - 1, -1):
            if dp[s - vol]:
                dp[s] = True
    # Find the maximum achievable sum not exceeding V
    max_sum = next((s for s in range(V, -1, -1) if dp[s]), 0)
    return V - max_sum

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Boolean DP to indicate which volumes can be achieved
    reachable = [False] * (V + 1)
    reachable[0] = True
    for i in range(n):
        vol = volumes[i]
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if reachable[cap - vol]:
                reachable[cap] = True
    # Find the largest achievable volume
    best = 0
    for cap in range(V, -1, -1):
        if reachable[cap]:
            best = cap
            break
    return V - best

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array where dp[j] is True if volume j can be achieved
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        # Iterate backwards to avoid using an item more than once
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True
    # Find the largest achievable volume not exceeding V
    max_vol = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_vol = j
            break
    # Remaining space is the difference between capacity and max occupied volume
    return V - max_vol

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [1] + [0]*m
    for cap in a:
        new_dp = [0]*(m+1)
        window = 0
        for k in range(m+1):
            window = (window + dp[k]) % MOD
            if k - cap - 1 >= 0:
                window = (window - dp[k - cap - 1]) % MOD
            new_dp[k] = window
        dp = new_dp
    return dp[m] % MOD

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key = key.lower()
    key_len = len(key)
    result = []
    for i, ch in enumerate(ciphertext):
        cipher_val = ord(ch.lower()) - 97
        key_val = ord(key[i % key_len]) - 97
        plain_val = (cipher_val - key_val + 26) % 26
        result.append(chr(plain_val + 97))
    return "".join(result)

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key:
        return ciphertext
    key_shifts = [ord(c.upper()) - ord('A') for c in key if c.isalpha()]
    if not key_shifts:
        return ciphertext
    result = []
    key_len = len(key_shifts)
    for i, ch in enumerate(ciphertext):
        shift = key_shifts[i % key_len]
        if ch.isupper():
            base = ord('A')
        else:
            base = ord('a')
        c_num = ord(ch) - base
        p_num = (c_num - shift) % 26
        result.append(chr(base + p_num))
    return ''.join(result)

def mod_inverse(a, b):
    if b <= 0:
        return None
    a %= b
    if a == 0:
        return None
    def egcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = egcd(y, x % y)
        return (g, t, s - (x // y) * t)
    g, inv, _ = egcd(a, b)
    if g != 1:
        return None
    return inv % b

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if b == 0:
            return a, 1, 0
        g, x, y = extended_gcd(b, a % b)
        return g, y, x - (a // b) * y

    g, x, _ = extended_gcd(a, b)
    if g != 1:
        return None
    return x % b

