def minimum_cost_to_merge_fruits(fruit_counts: list[int]) -> int:
    from heapq import heapify, heappop, heappush
    if len(fruit_counts) <= 1:
        return 0
    heapify(fruit_counts)
    total_cost = 0
    while len(fruit_counts) > 1:
        a = heappop(fruit_counts)
        b = heappop(fruit_counts)
        cost = a + b
        total_cost += cost
        heappush(fruit_counts, cost)
    return total_cost)

