    # Length of longest increasing subsequence ending at each index
    inc_left = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc_left[j] + 1 > inc_left[i]:
                inc_left[i] = inc_left[j] + 1
    # Compute LIS on reversed array to get length of increasing subsequence
    # starting at each index (which corresponds to decreasing subsequence ending at index)
    rev = heights[::-1]
