    for i in range(n):
        for j in range(i):
            if rev[j] < rev[i] and inc_rev[j] + 1 > inc_rev[i]:
                inc_rev[i] = inc_rev[j] + 1
    # Map back to original indices
    inc_right = [0] * n
    for i in range(n):
        inc_right[i] = inc_rev[n - 1 - i]
    # Longest bitonic subsequence length
    best = 0
    for i in range(n):
        curr = inc_left[i] + inc_right[i] - 1
        if curr > best:
            best = curr
    return n - best

