def minimum_students_to_leave(heights):
    """
    Calculates the minimum number of students that need to leave so that the remaining
    heights form a bitonic sequence (strictly increasing then strictly decreasing).

    Parameters:
    heights (List[int]): List of student heights.

    Returns:
    int: Minimum number of students to leave.
    """
    n = len(heights)
    if n <= 1:
        return 0

    # Compute LIS ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute LDS starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        # subtract 1 because the peak element is counted twice
        cur = lis[i] + lds[i] - 1
        if cur > max_bitonic:
            max_bitonic = cur

    return n - max_bitonic

def min_groups(w, n, prices):
