            r -= 1
        else:
            r -= 1
        count += 1
    return count

def min_groups(w, n, prices):
    prices.sort()
    i, j = 0, len(prices) - 1
    groups = 0
    while i <= j:
        if i == j:
            groups += 1
            break
        if prices[i] + prices[j] <= w:
            i += 1
            j -= 1
        else:
            j -= 1
        groups += 1
    return groups

def hanoi_double_iterative(n: int) -> int:
    if n <= 0:
        return 0
    moves = 2  # base case for n = 1
    for _ in range(2, n + 1):
        moves = 2 * moves + 2  # iterative application of T(n) = 2*T(n-1) + 2
    return moves

def hanoi_double_iterative(n: int) -> int:
    if n <= 0:
        return 0
    moves = 0
    power_of_two = 2  # 2^1
    for _ in range(n):
        moves += power_of_two
        power_of_two <<= 1
    return moves
